export const AEO_2017: PYQQuestion[] = [

  // ══ PART A: GENERAL STUDIES & TELANGANA (30 Questions) ══

  // Telangana History, Culture & Geography
  { id:"aeo17_001", year:2017, subject:"general-studies", question:"The Telangana Rashtra Samiti (TRS) was founded in:", options:["1990","2001","2004","2014"], correct:1, explanation:"TRS (Telangana Rashtra Samiti) was founded on 27 April 2001 by K. Chandrashekar Rao (KCR). It was formed specifically to fight for a separate Telangana state and led the agitation that resulted in Telangana's formation in 2014." },
  { id:"aeo17_002", year:2017, subject:"general-studies", question:"Warangal fort was built by which Kakatiya ruler?", options:["Prataparudra II","Ganapati Deva","Rudrama Devi","Betaraja I"], correct:1, explanation:"The Warangal fort (Orugallu Kota) with its famous stone gateways (Swayambhuvashivam) was built primarily under Ganapati Deva (1199–1262 AD), the powerful Kakatiya ruler who also built the Ramappa Temple (UNESCO World Heritage Site)." },
  { id:"aeo17_003", year:2017, subject:"general-studies", question:"'Ramappa Temple' in Telangana was recently declared as:", options:["National Park","UNESCO World Heritage Site","State Protected Monument","Botanical Garden"], correct:1, explanation:"Ramappa Temple (Ramalingeswara temple) at Palampet, Mulugu district, built in 1213 CE under Kakatiya general Recharla Rudra, was inscribed as a UNESCO World Heritage Site in July 2021. It is the only temple named after its sculptor (Ramappa)." },
  { id:"aeo17_004", year:2017, subject:"general-studies", question:"Telangana's official language is:", options:["Hindi","Telugu","Urdu","Both Telugu and Urdu"], correct:3, explanation:"Telangana has two official languages: Telugu (primary official language) and Urdu. Urdu has co-official status given Hyderabad's historical Nizam-era heritage and the significant Urdu-speaking population." },
  { id:"aeo17_005", year:2017, subject:"general-studies", question:"The Hyderabad Liberation Day (Telangana Formation in 1948) is observed on:", options:["2 June","17 September","15 August","1 November"], correct:1, explanation:"17 September is observed as Hyderabad Liberation Day (also called Hyderabad Merger Day) marking the integration of Hyderabad state into India through Police Action/Operation Polo in 1948. It is a public holiday in Telangana." },
  { id:"aeo17_006", year:2017, subject:"general-studies", question:"Srisailam Wildlife Sanctuary forms part of which Tiger Reserve?", options:["Kawal Tiger Reserve","Nagarjunasagar-Srisailam Tiger Reserve","Amrabad Tiger Reserve","Papikonda Tiger Reserve"], correct:1, explanation:"Srisailam Wildlife Sanctuary is part of the larger Nagarjunasagar-Srisailam Tiger Reserve (India's largest tiger reserve spanning 3,728 sq km across Telangana and AP). However, Amrabad TR was carved out of this in 2014 as Telangana's separate tiger reserve." },
  { id:"aeo17_007", year:2017, subject:"general-studies", question:"Pochampally Ikat is a GI (Geographical Indication) product of:", options:["Warangal district","Karimnagar district","Nalgonda district (Bhoodan Pochampally)","Adilabad district"], correct:2, explanation:"Pochampally Ikat sarees/fabric got GI tag — Bhoodan Pochampally is in Nalgonda district (though now administratively part of the merged Yadadri Bhuvanagiri district). The weavers use the tie-and-dye 'Ikat' technique for distinctive patterns." },
  { id:"aeo17_008", year:2017, subject:"general-studies", question:"Which district of Telangana is known as 'Rice Bowl of Telangana'?", options:["Nalgonda","Karimnagar","Warangal","Khammam"], correct:1, explanation:"Karimnagar district (and its split districts Rajanna Sircilla, Jagtial, Peddapalli) is known as the 'Rice Bowl of Telangana' due to its extensive paddy cultivation under the Sriram Sagar (Nizamsagar) and Sriramsagar Project canals." },
  { id:"aeo17_009", year:2017, subject:"general-studies", question:"'Singareni Collieries' (SCCL), Telangana's major coal mining company, is a joint venture between:", options:["Central Govt. only","Telangana State Government and Central Government (51:49)","Private sector only","International mining companies"], correct:1, explanation:"SCCL (Singareni Collieries Company Limited) is jointly owned by Telangana State Government (51%) and Government of India/BHC (49%). It operates the largest coalfield in South India, mainly in Godavari and Pranahita-Chevella coalfields." },
  { id:"aeo17_010", year:2017, subject:"general-studies", question:"The 'Telangana State Development Planning Society' (TSDPS) is engaged in:", options:["Agricultural research","Geospatial data management, GIS mapping, and planning support for Telangana","Industrial promotion","Tourism development"], correct:1, explanation:"TSDPS (Telangana State Development Planning Society) is the nodal agency for geospatial technology, GIS-based planning, real-time data analytics (T-HIMS, Dharani land records), and development planning for Telangana." },

  // Indian Polity, Economy & Current Affairs
  { id:"aeo17_011", year:2017, subject:"general-studies", question:"'Goods and Services Tax' (GST) was implemented in India from:", options:["1 April 2017","1 July 2017","1 January 2018","26 January 2017"], correct:1, explanation:"GST (Goods and Services Tax) — India's comprehensive indirect tax reform — was implemented from 1 July 2017, replacing multiple central and state taxes (excise, service tax, VAT, etc.) with a unified tax system. It was passed by Parliament in August 2016." },
  { id:"aeo17_012", year:2017, subject:"general-studies", question:"'Demonetisation' of ₹500 and ₹1000 notes in India was announced on:", options:["8 November 2016","1 January 2017","15 August 2016","2 October 2016"], correct:0, explanation:"PM Narendra Modi announced demonetisation (withdrawal of legal tender status) of ₹500 and ₹1000 notes on 8 November 2016 (at 8 PM) with the objective of combating black money, counterfeit notes, and corruption." },
  { id:"aeo17_013", year:2017, subject:"general-studies", question:"The Right to Information (RTI) Act was enacted in:", options:["2000","2003","2005","2007"], correct:2, explanation:"The Right to Information Act was enacted by Parliament on 15 June 2005 and came into effect on 12 October 2005. It provides citizens the right to access information from public authorities, promoting transparency and accountability." },
  { id:"aeo17_014", year:2017, subject:"general-studies", question:"Under MGNREGA, if work is not provided within 15 days of application, the state must pay:", options:["Double wages","No payment — wait for work","Unemployment allowance (minimum 25% of minimum wage for 1st 30 days, 50% thereafter)","Free food grain"], correct:2, explanation:"MGNREGA mandates that if employment is not provided within 15 days of application, the state must pay unemployment allowance (1/4 wage rate for first 30 days, 1/2 wage rate thereafter) to the applicant household." },
  { id:"aeo17_015", year:2017, subject:"general-studies", question:"Which state became the first to achieve 100% household electrification under the Saubhagya scheme?", options:["Gujarat","Himachal Pradesh","Telangana","Chhattisgarh"], correct:2, explanation:"Telangana was the first state in India to achieve 100% household electrification. Through 'Haritha Haram' and other schemes, Telangana provided 24-hour reliable power supply to both agricultural and domestic consumers." },
  { id:"aeo17_016", year:2017, subject:"general-studies", question:"'Pradhan Mantri Ujjwala Yojana' (PMUY) was launched to provide free LPG connections to:", options:["All BPL women above poverty line","Women from BPL (Below Poverty Line) households","Only SC/ST families","All rural families"], correct:1, explanation:"PMUY (launched May 2016) provides free LPG cooking gas connections to women belonging to BPL households. Target: 8 crore connections. It aims to replace unhealthy cooking fuel (firewood, dung cakes) and reduce indoor air pollution." },

  // Science & Technology
  { id:"aeo17_017", year:2017, subject:"general-studies", question:"'Mission Indradhanush' is related to:", options:["Space mission","Universal immunisation of children and pregnant women against 12 vaccine-preventable diseases","Rural electrification","Irrigation project"], correct:1, explanation:"Mission Indradhanush (launched December 2014) aims to immunise all unvaccinated/partially vaccinated children (0–2 years) and pregnant women against 12 vaccine-preventable diseases (polio, measles, TB, hepatitis B, etc.). Named after the 7-colour rainbow." },
  { id:"aeo17_018", year:2017, subject:"general-studies", question:"'Aadhaar' biometric identity programme is governed by which Act?", options:["Information Technology Act","Aadhaar (Targeted Delivery of Financial and Other Subsidies, Benefits and Services) Act 2016","The Constitution","National Security Act"], correct:1, explanation:"Aadhaar Act 2016 provides the legal framework for UIDAI (Unique Identification Authority of India) to collect biometric data, issue 12-digit Aadhaar numbers, and link Aadhaar to welfare schemes for targeted delivery of benefits." },
  { id:"aeo17_019", year:2017, subject:"general-studies", question:"ISRO successfully launched 104 satellites in a single mission (PSLV-C37) in:", options:["2015","2016","2017","2018"], correct:2, explanation:"On 15 February 2017, ISRO launched 104 satellites simultaneously using PSLV-C37, setting a world record for most satellites launched in a single rocket. This included India's Cartosat-2D and 101 international nano-satellites." },
  { id:"aeo17_020", year:2017, subject:"general-studies", question:"'Direct Benefit Transfer' (DBT) in India aims to:", options:["Increase government spending","Transfer subsidies/benefits directly to beneficiaries' bank accounts, eliminating middlemen","Reduce agricultural production","Promote exports"], correct:1, explanation:"DBT transfers government subsidies and welfare scheme payments (fertilizer subsidy, scholarships, MGNREGA wages, PM-KISAN, LPG subsidy) directly to beneficiaries' Aadhaar-linked bank accounts, reducing leakage and ensuring targeted delivery." },

  // Aptitude & Reasoning
  { id:"aeo17_021", year:2017, subject:"general-studies", question:"A field is 200m × 150m. If fencing costs ₹15 per metre, what is the total cost of fencing the field?", options:["₹10,500","₹52,500","₹67,500","₹30,000"], correct:0, explanation:"Wait - this needs recalculation. Perimeter = 2(200+150) = 2×350 = 700m. Total cost = 700 × 15 = ₹10,500. Answer: ₹10,500.", explanation:"Perimeter = 2×(200+150) = 700m. Cost = 700 × ₹15 = ₹10,500." },
  { id:"aeo17_022", year:2017, subject:"general-studies", question:"If a farmer sells 40 kg of paddy at ₹1,410 per quintal, what amount does he receive?", options:["₹56,400","₹564","₹5,640","₹56.40"], correct:1, explanation:"1 quintal = 100 kg. 40 kg = 0.4 quintal. Amount = 0.4 × 1410 = ₹564. The farmer receives ₹564 for 40 kg of paddy at MSP rate." },
  { id:"aeo17_023", year:2017, subject:"general-studies", question:"In a village, 60% of households have a radio and 40% have a TV. 25% have both. What % have neither?", options:["25%","35%","15%","20%"], correct:0, explanation:"Using set theory: P(Radio∪TV) = 60+40-25 = 75%. P(neither) = 100-75 = 25%. So 25% of households have neither radio nor TV." },
  { id:"aeo17_024", year:2017, subject:"general-studies", question:"If today is Wednesday, what day will it be 100 days from now?", options:["Monday","Tuesday","Wednesday","Friday"], correct:3, explanation:"100 ÷ 7 = 14 weeks + 2 days. Wednesday + 2 days = Friday. So 100 days from Wednesday is Friday." },
  { id:"aeo17_025", year:2017, subject:"general-studies", question:"Which word does NOT belong: Kharif, Rabi, Zaid, Annual?", options:["Kharif","Rabi","Zaid","Annual"], correct:3, explanation:"Kharif, Rabi, and Zaid are crop seasons in India (Kharif=rainy, Rabi=winter, Zaid=summer). 'Annual' refers to plant life cycle (completes in one year), not a cropping season — it is the odd one out." },

  // Telangana Current Affairs 2016-17
  { id:"aeo17_026", year:2017, subject:"general-studies", question:"Which project was launched in Telangana for integrated rural development named after a Kakatiya queen?", options:["Mission Bhagiratha","Mission Kakatiya","Indira Prabha","Rythu Bandhu"], correct:1, explanation:"Mission Kakatiya (launched March 2015) aims to restore the historical irrigation tank network of Telangana, inspired by the Kakatiya dynasty's sophisticated water management. Target: restoration of 46,531 tanks across Telangana." },
  { id:"aeo17_027", year:2017, subject:"general-studies", question:"'Haritha Haram' programme in Telangana aims to achieve what percentage forest and tree cover?", options:["24%","33%","50%","40%"], correct:2, explanation:"Haritha Haram (Green Garland) programme launched in 2015 aims to increase Telangana's tree cover from the current 24% to 33% initially (as per National Forest Policy) and ultimately to 50% of geographic area — planting 230 crore saplings." },
  { id:"aeo17_028", year:2017, subject:"general-studies", question:"The Kaleshwaram Lift Irrigation Scheme (KLIS) was approved to irrigate how many acres?", options:["5 lakh acres","18.25 lakh acres","37 lakh acres","50 lakh acres"], correct:2, explanation:"Kaleshwaram Lift Irrigation Scheme is designed to irrigate 18.25 lakh acres (in Phase-I). However, the broader KLIS vision covers 37 lakh acres and provides drinking water to Hyderabad and other towns. It is the world's largest multi-stage lift irrigation project." },
  { id:"aeo17_029", year:2017, subject:"general-studies", question:"'TS-iPASS' (Telangana State Industrial Project Approval and Self Certification System) was implemented to:", options:["Improve agricultural marketing","Streamline industrial approvals within 15 days for new investment and employment generation","Control pollution","Manage land records"], correct:1, explanation:"TS-iPASS is an online single-window system for industrial approvals in Telangana. It approves all clearances (permissions, licences) for new industrial investments within 15 days, making Telangana one of the most investor-friendly states." },
  { id:"aeo17_030", year:2017, subject:"general-studies", question:"Telangana's total number of districts after reorganisation in 2016 is:", options:["10","23","31","33"], correct:3, explanation:"On 11 October 2016, Telangana was reorganised from 10 districts to 31 districts (later expanded to 33). The reorganisation was done to bring administration closer to people and implement government schemes more effectively." },

  // ══ PART B: AGRICULTURE (70 Questions) ══

  // Agricultural Extension (15 Qs)
  { id:"aeo17_031", year:2017, subject:"extension", question:"'Kisan Mela' is an example of which type of extension method?", options:["Individual method","Group method","Mass contact method","None"], correct:1, explanation:"Kisan Mela (Farmers' Fair) is a group extension method that brings together large groups (50–500 farmers) for demonstrations, exhibitions, competitions, and interaction with scientists. It is more than a group meeting but less than mass media." },
  { id:"aeo17_032", year:2017, subject:"extension", question:"The main purpose of 'result demonstration' in extension education is to:", options:["Show HOW to do something","Show WHAT results can be obtained by adopting a recommended practice","Train extension workers","Sell agricultural inputs"], correct:1, explanation:"Result demonstration shows farmers WHAT results (yield, profit, quality) can be obtained by adopting a recommended technology on their own or a neighbouring farm. It motivates adoption by showing proof of benefit in local conditions." },
  { id:"aeo17_033", year:2017, subject:"extension", question:"Under which scheme are Soil Health Cards prepared and distributed to farmers?", options:["PM-KISAN","National Food Security Mission","Soil Health Card Scheme (under NMSA)","RKVY"], correct:2, explanation:"Soil Health Cards are issued under the Soil Health Card Scheme, a sub-scheme of NMSA (National Mission for Sustainable Agriculture). Cards are issued every 2 years based on soil testing, providing crop-wise nutrient recommendations." },
  { id:"aeo17_034", year:2017, subject:"extension", question:"'Farmer Producer Organisation' (FPO) is essentially a:", options:["Government agricultural department","Collective business enterprise owned by farmers for better input access, production, and marketing","NGO funded by foreign aid","Private company with shareholder farmers having no voting rights"], correct:1, explanation:"FPO is a type of Producer Company (registered under Companies Act 2013) owned and managed by farmers. Members share profits, access quality inputs at reduced cost, and collectively market produce at better prices." },
  { id:"aeo17_035", year:2017, subject:"extension", question:"'Agri-Clinics and Agri-Business Centres' scheme is implemented by:", options:["ICAR","NABARD with MANAGE to promote agri-entrepreneurship","Ministry of Finance","Reserve Bank of India"], correct:1, explanation:"Agri-Clinics & Agri-Business Centres (ACABC) scheme is implemented jointly by NABARD (credit) and MANAGE (training) to encourage agriculture graduates to set up agri-ventures (input shops, diagnostic labs, soil testing) as entrepreneurs." },
  { id:"aeo17_036", year:2017, subject:"extension", question:"'Gram Panchayat Agriculture Plan' (GPAP) is prepared by:", options:["State Agriculture Department alone","KVK scientists","Village-level planning with farmer participation and GP involvement","District Collector's office"], correct:2, explanation:"GPAP (Gram Panchayat Agriculture Plan) is a decentralised planning exercise where farmers, Gram Panchayat members, extension workers, and line department officers jointly prepare an agriculture development plan for each village/GP." },
  { id:"aeo17_037", year:2017, subject:"extension", question:"'Zero-based budgeting' in extension programme planning means:", options:["Planning without any budget","Each planning cycle starts fresh without assuming continuation of past activities — justifying every expenditure","Using only government funds","Planning based on previous year's budget"], correct:1, explanation:"Zero-based budgeting (ZBB) requires every expense in a programme to be justified for each budget cycle, starting from 'zero' base. Unlike incremental budgeting (building on previous budget), ZBB prevents continuation of ineffective activities." },
  { id:"aeo17_038", year:2017, subject:"extension", question:"'IFFCO Kisan' app provides what service to farmers?", options:["Only fertilizer ordering","Agri-advisory, market prices, weather, and query resolution in regional languages","Only government scheme information","Only soil testing request"], correct:1, explanation:"IFFCO Kisan app provides comprehensive agricultural services: crop advisory, weather forecast, market prices, soil health information, government schemes, video tutorials in multiple regional languages, targeting 7 crore+ farmer users." },
  { id:"aeo17_039", year:2017, subject:"extension", question:"'Technology backstopping' in KVK means:", options:["KVK funding farmers directly","KVK providing technical support, guidance, and on-call advisory to extension workers in the district","KVK selling seeds and fertilizers","KVK managing irrigation projects"], correct:1, explanation:"Technology backstopping is a core function of KVKs: providing technical guidance, troubleshooting, reference material, and on-demand advisory to extension workers (AAOs, AOs) when they encounter technical problems beyond their competence." },
  { id:"aeo17_040", year:2017, subject:"extension", question:"The 'Revised Yellow Revolution' initiative is related to:", options:["Paddy production","Edible oilseeds production (to achieve self-sufficiency and reduce import dependence)","Horticulture development","Fisheries development"], correct:1, explanation:"Yellow Revolution refers to the development of oilseed production in India. The revised/second yellow revolution aims to increase domestic oilseed production (groundnut, mustard, sunflower, soybean) to reduce India's large import bill for edible oils." },
  { id:"aeo17_041", year:2017, subject:"extension", question:"Which of the following is a National Level Farmers Award?", options:["Padma Shri only","Krishi Karman Award (for states) and Pandit Deen Dayal Upadhyay Puraskar (for farmers)","Arjuna Award","Dronacharya Award"], correct:1, explanation:"National level agricultural awards include: Krishi Karman Award (for states achieving best food grain production) and various farmer-level awards including Pandit Deen Dayal Upadhyay Krishi Vigyan Protsahan Puraskar for outstanding farmer achievement." },
  { id:"aeo17_042", year:2017, subject:"extension", question:"'Social audit' in MGNREGA requires that all works and expenditure records be:", options:["Available only to government auditors","Publicly displayed at Gram Panchayat and verified at Gram Sabha meetings","Maintained only at district headquarters","Kept confidential"], correct:1, explanation:"MGNREGA mandates periodic social audits where all work details, wages paid, and expenditure records are publicly displayed at Gram Panchayat level and read out at Gram Sabha for community verification — empowering citizens as watchdogs." },
  { id:"aeo17_043", year:2017, subject:"extension", question:"'Rythu Vedika' centres in Telangana are established at:", options:["State headquarters only","Mandal level for providing agricultural information, weather data, and advisory services to farmers","Village level only","District collector's office"], correct:1, explanation:"Rythu Vedika (Farmer Forum) centres at mandal level serve as information and service delivery hubs for farmers — providing weather information, market prices, advisory services, scheme information, and facilitating interaction with agriculture department officials." },
  { id:"aeo17_044", year:2017, subject:"extension", question:"Under 'PM Fasal Bima Yojana', the premium rate for kharif crops is:", options:["5% of sum insured","2% of sum insured (or actuarial rate, whichever is less) for notified crops","10% of sum insured","1% of sum insured"], correct:1, explanation:"PMFBY premium rates: 2% (or actuarial rate if lower) for Kharif crops, 1.5% for Rabi crops, 5% for annual commercial/horticultural crops. Premium above these rates is shared equally between Central and State governments." },
  { id:"aeo17_045", year:2017, subject:"extension", question:"The 'National Agricultural Market' (e-NAM) was designed to:", options:["Replace APMCs entirely","Create an online unified national market linking existing APMCs for transparent price discovery","Establish government-owned shops","Import agricultural produce"], correct:1, explanation:"e-NAM does NOT replace APMCs — it creates an online trading layer connecting existing APMC mandis. Farmers, traders, and buyers can trade on the platform using transparent e-bidding, reducing market fragmentation and improving price realisation." },

  // Agronomy (15 Qs)
  { id:"aeo17_046", year:2017, subject:"agronomy", question:"Which nutrient deficiency causes 'Khaira disease' in paddy?", options:["Nitrogen","Zinc","Iron","Manganese"], correct:1, explanation:"Khaira disease of paddy is caused by Zinc (Zn) deficiency. Symptoms appear 2–4 weeks after transplanting: pale yellow-brown spots on leaves, stunting, delayed tillering, and poor root development. Managed by ZnSO4 application." },
  { id:"aeo17_047", year:2017, subject:"agronomy", question:"'Herbicide resistance' in weeds is best managed by:", options:["Using more herbicide","Rotating herbicide modes of action, using mixtures, and integrating non-chemical methods","Stopping herbicide use entirely","Using the same herbicide at higher doses"], correct:1, explanation:"Herbicide resistance management: rotate herbicide modes of action (different sites of action), use tank mixes of herbicides with different modes of action, integrate mechanical/cultural methods (crop rotation, hand weeding) to reduce selection pressure." },
  { id:"aeo17_048", year:2017, subject:"agronomy", question:"'Aerobic rice cultivation' is suitable for:", options:["Low-lying waterlogged areas","Well-drained non-puddled fields with sprinkler or drip irrigation","Coastal saline areas","Terraced hill slopes only"], correct:1, explanation:"Aerobic rice is grown in non-puddled, non-flooded, well-drained soils (like upland crops) using varieties adapted to aerobic conditions (DSR-1, MAS 946-1). It saves 40–55% water compared to flooded rice with 20–30% yield reduction." },
  { id:"aeo17_049", year:2017, subject:"agronomy", question:"'Ratoon cropping' in sugarcane involves:", options:["Planting fresh setts every year","Allowing new shoots to emerge from stubble after harvest for a second crop","Transplanting sugarcane","Grafting sugarcane varieties"], correct:1, explanation:"Ratoon cropping in sugarcane harvests a second (and sometimes third) crop from shoots (ratoon/stubble shoots) that emerge from the stump left after harvesting the plant crop. Ratoon cane saves 20–25% input costs." },
  { id:"aeo17_050", year:2017, subject:"agronomy", question:"Telangana's cotton is mostly grown in which districts?", options:["Karimnagar and Warangal (paddy districts)","Adilabad, Komuram Bheem, and Nirmal districts (northern districts)","Only Hyderabad","Southern Telangana only"], correct:1, explanation:"Cotton is predominantly grown in northern Telangana — Adilabad, Komuram Bheem, Mancherial, Nirmal, Nizamabad, and Jagityal districts. These areas have black cotton soils (Vertisols) and receive adequate rainfall for cotton cultivation." },
  { id:"aeo17_051", year:2017, subject:"agronomy", question:"What is the recommended N:P₂O₅:K₂O fertilizer dose for high-yielding paddy in Telangana (kg/ha)?", options:["40:20:0","80:40:40","120:60:40","150:75:75"], correct:2, explanation:"Recommended NPK dose for high-yielding paddy in Telangana: 120 kg N : 60 kg P₂O₅ : 40 kg K₂O per hectare (for districts with good K status). This is applied in 3 splits for N (basal, AT, PI) and basal for P and K." },
  { id:"aeo17_052", year:2017, subject:"agronomy", question:"'Transplanted rice' compared to direct seeded rice has the advantage of:", options:["Lower water requirement","Better weed control due to anaerobic conditions after transplanting","Lower labour cost","Higher seed requirement"], correct:1, explanation:"Transplanted rice creates anaerobic (flooded) conditions after transplanting, suppressing germination of most annual weeds. This gives a significant advantage in weed management compared to dry-seeded direct sown rice." },
  { id:"aeo17_053", year:2017, subject:"agronomy", question:"'Mulching' in vegetable cultivation helps in:", options:["Increasing soil compaction","Conserving soil moisture, regulating soil temperature, and suppressing weeds","Increasing evaporation","Promoting soil erosion"], correct:1, explanation:"Mulching (covering soil with organic or plastic materials) conserves soil moisture by reducing evaporation, moderates extreme soil temperatures, suppresses weed germination, prevents soil splash erosion, and (organic mulch) adds organic matter." },
  { id:"aeo17_054", year:2017, subject:"agronomy", question:"National Average of paddy yield in India is approximately:", options:["1.5 t/ha","2.0 t/ha","2.6 t/ha","4.5 t/ha"], correct:2, explanation:"India's national average paddy yield is approximately 2.6 t/ha (2,600 kg/ha). Punjab achieves ~4.5 t/ha (highest) while Telangana averages ~2.8–3.0 t/ha. Global average is ~4.7 t/ha. Potential yield with best varieties is 8–10 t/ha." },
  { id:"aeo17_055", year:2017, subject:"agronomy", question:"'HADP' (High Altitude Dry Plateaus) farming problems in Telangana include:", options:["Excess rainfall and flooding","Drought, shallow red soils, low organic matter, and rainfed conditions","Salinity and waterlogging","Frost damage"], correct:1, explanation:"High altitude dry plateau areas (northern and eastern Telangana) face: erratic and low rainfall (<750mm), shallow red soils with low water holding capacity and organic matter, predominantly rainfed conditions, and high crop risk." },
  { id:"aeo17_056", year:2017, subject:"agronomy", question:"'Fertigation' refers to:", options:["Irrigation water quality testing","Application of water-soluble fertilizers through irrigation systems (drip/sprinkler)","Foliar fertilizer spraying","Applying fertilizer in furrows manually"], correct:1, explanation:"Fertigation is the technique of applying fertilizers dissolved in water through the irrigation system (drip or sprinkler). It delivers nutrients directly to the root zone, improving fertilizer use efficiency by 20–30% compared to soil application." },
  { id:"aeo17_057", year:2017, subject:"agronomy", question:"Which crop is grown as a 'trap crop' for Spodoptera (fall armyworm/leaf armyworm) in cotton?", options:["Maize (planted as border trap crop)","Paddy","Soybean","Castor"], correct:0, explanation:"Maize planted as a border trap crop around cotton attracts Spodoptera litura (cotton/maize leaf armyworm) away from cotton. When pest population builds up on maize trap rows, targeted pesticide can be applied only on trap rows." },
  { id:"aeo17_058", year:2017, subject:"agronomy", question:"'Crop diversification' in Telangana context means shifting from:", options:["Traditional food crops only","Paddy mono-culture to include pulses, oilseeds, vegetables, and horticulture crops for profitability","Reducing total crop area","Importing crops instead of growing"], correct:1, explanation:"Crop diversification in Telangana encourages farmers to shift from water-intensive paddy mono-culture to pulses (redgram, moong), oilseeds (sunflower, groundnut), vegetables, and horticulture, improving income stability and natural resource conservation." },
  { id:"aeo17_059", year:2017, subject:"agronomy", question:"'Pulses Mission' in Telangana aims to increase area under:", options:["Only black gram","Redgram, bengal gram, green gram, and black gram — all major pulses","Groundnut only","Soybean only"], correct:1, explanation:"Pulses Mission/NHM Pulses component in Telangana promotes all four major pulses: redgram (pigeon pea, major kharif pulse), bengal gram (chickpea, rabi), green gram (moong, kharif/zaid), and black gram (urad, kharif) through HYV seeds and input support." },
  { id:"aeo17_060", year:2017, subject:"agronomy", question:"The 'FLD' (Front Line Demonstration) in crops is conducted at:", options:["Research station under controlled conditions","On farmers' fields using farmers' land and resources with research institute backstopping","At government farms only","In laboratories only"], correct:1, explanation:"FLDs are conducted on farmers' own fields (not research stations) using the farmer's land and labour, with technical backstopping from KVK/ICAR. This demonstrates real farm-level performance of new varieties/practices in farmers' conditions." },

  // Soil Science (12 Qs)
  { id:"aeo17_061", year:2017, subject:"soil-science", question:"Telangana's dominant soil order covering about 45% of geographical area is:", options:["Entisols","Alfisols (Red soils)","Vertisols (Black cotton soils)","Inceptisols"], correct:1, explanation:"Alfisols (Red soils — loamy and sandy loam textured, low in organic matter, well-drained) cover about 45% of Telangana's area. Vertisols (black cotton soils) cover about 30% of the area, predominantly in Nalgonda, Mahbubnagar, and Warangal regions." },
  { id:"aeo17_062", year:2017, subject:"soil-science", question:"'Soil test based recommendations' require soil sampling up to which depth for dryland crops?", options:["0–5 cm","0–15 cm (topsoil/plough layer)","0–30 cm","0–60 cm"], correct:1, explanation:"For dryland field crops, soil samples are collected from 0–15 cm depth (plough layer) for routine nutrient analysis (N, P, K, pH, EC). For deep-rooted crops or subsoil problems, 15–30 cm is also collected." },
  { id:"aeo17_063", year:2017, subject:"soil-science", question:"'Acidic soils' are common in which regions of Telangana?", options:["Black cotton soil areas (Nalgonda, Mahbubnagar)","High rainfall forest areas of Adilabad, Khammam, and Bhadradri-Kothagudem","Delta areas","Arid western Telangana"], correct:1, explanation:"Acidic soils (pH < 6.0) are found in high rainfall areas of Adilabad, Asifabad, Khammam, and Bhadradri-Kothagudem where leaching is high. Lime application is recommended. Black cotton soil areas are neutral to alkaline." },
  { id:"aeo17_064", year:2017, subject:"soil-science", question:"The 'Critical Level' of available Zinc (Zn) in soil is:", options:["0.3 mg/kg (DTPA extractable)","5 mg/kg","10 mg/kg","0.01 mg/kg"], correct:0, explanation:"The critical level for Zn in soil (DTPA extraction method) is 0.3 mg/kg (Lindsay and Norvell method). Soils with DTPA-Zn below 0.3 mg/kg are likely to show crop response to zinc application. This threshold is used across India for recommendations." },
  { id:"aeo17_065", year:2017, subject:"soil-science", question:"'Nitrification inhibitor' DCD (Dicyandiamide) when coated on urea helps in:", options:["Increasing P availability","Slowing conversion of ammonium to nitrate, reducing N losses through leaching and denitrification","Improving K uptake","Controlling weeds"], correct:1, explanation:"DCD (Dicyandiamide) and NBPT inhibit Nitrosomonas bacteria activity, slowing ammonium → nitrate conversion (nitrification). This keeps N as NH4+ (less mobile) in soil longer, reducing nitrate leaching and denitrification losses." },
  { id:"aeo17_066", year:2017, subject:"soil-science", question:"Composting of organic matter is primarily an:", options:["Anaerobic process only","Aerobic microbiological decomposition process (aerobic composting is most common)","Chemical reaction with water","Physical breakdown only"], correct:1, explanation:"Aerobic composting (the Bangalore/hot method) involves microbial decomposition by aerobic organisms (bacteria, fungi, actinomycetes) under aerobic conditions, generating heat (55-65°C) that kills pathogens and weed seeds. Anaerobic composting also exists." },
  { id:"aeo17_067", year:2017, subject:"soil-science", question:"'Soil electrical conductivity' (EC) is used to assess:", options:["Soil pH","Soil salinity (soluble salt concentration)","Soil texture","Soil organic matter content"], correct:1, explanation:"Electrical conductivity (EC) of soil saturation extract (ECe) measures total dissolved salts — primary indicator of soil salinity. ECe > 4 dS/m is saline; most crops are affected above 2–4 dS/m depending on crop sensitivity." },
  { id:"aeo17_068", year:2017, subject:"soil-science", question:"'Biofertilizers' used for phosphorus solubilisation in soil are:", options:["Rhizobium","PSB — Phosphate Solubilising Bacteria (Bacillus, Pseudomonas sp.)","Azotobacter","BGA"], correct:1, explanation:"Phosphate Solubilising Bacteria (PSB) like Bacillus subtilis, Pseudomonas fluorescens, and Aspergillus niger produce organic acids and enzymes that convert insoluble soil phosphates (Ca-P, Fe-P, Al-P) to plant-available soluble forms." },
  { id:"aeo17_069", year:2017, subject:"soil-science", question:"The 'Critical Limit' of available Phosphorus (P) in soil by Olsen's method is:", options:["2 kg/ha","10–12 kg/ha (21–25 kg P2O5/ha)","50 kg/ha","100 kg/ha"], correct:1, explanation:"Critical level for available P by Olsen's method (NaHCO3 extraction) is approximately 10–12 kg P/ha (21–25 kg P2O5/ha). Below this, crop shows response to P application; above this, additional P application gives marginal or no response." },
  { id:"aeo17_070", year:2017, subject:"soil-science", question:"'Micronutrient deficiency' in crops is effectively managed by:", options:["Increasing NPK doses","Soil application and foliar spray of specific micronutrient salts (ZnSO4, FeSO4, Borax)","Adding more organic matter only","Changing crop variety"], correct:1, explanation:"Micronutrient deficiencies are corrected by: soil application of specific salts (ZnSO4 at 25 kg/ha, Borax at 5–10 kg/ha) and/or foliar sprays (0.5% ZnSO4, 0.1% FeSO4, 0.1% Borax). Chelated forms (EDTA-Zn, Fe-EDTA) are more effective on alkaline soils." },
  { id:"aeo17_071", year:2017, subject:"soil-science", question:"Soil Organic Carbon (SOC) in most Telangana red soils is generally:", options:["High (>3%)","Medium (1.5–3%)","Low (<0.5%)","Very High (>5%)"], correct:2, explanation:"Telangana's red (alfisol) soils are characteristically low in organic matter (OC < 0.5%, often 0.2–0.4%) due to high temperatures accelerating decomposition, low biomass return to soil, and burning of crop residues." },
  { id:"aeo17_072", year:2017, subject:"soil-science", question:"'Carbon Sequestration' through agriculture means:", options:["Burning crop residues to release CO2","Storing atmospheric CO2 in soil organic matter through crop production practices (zero-till, cover crops, organic amendments)","Applying more chemical fertilizers","Converting agricultural land to forest"], correct:1, explanation:"Agricultural carbon sequestration stores atmospheric CO2 as soil organic carbon (SOC) through: zero/reduced tillage (less SOC oxidation), cover cropping, organic amendments, agroforestry, and perennial crops. Each 1% increase in SOC sequesters ~15 t CO2/ha." },

  // Plant Protection (13 Qs)
  { id:"aeo17_073", year:2017, subject:"entomology", question:"'Crop monitoring' for pest management involves:", options:["Spraying pesticides at fixed calendar intervals","Regular scouting of fields to count pest and natural enemy populations for ETL-based decisions","Applying pesticides preventively at crop emergence","Contacting extension officer only when severe damage occurs"], correct:1, explanation:"Crop monitoring (pest scouting) involves systematic field visits at fixed intervals to observe pest populations, natural enemies, and crop damage. Data is compared against ETL to make economically rational, ecologically sound decisions about when/whether to spray." },
  { id:"aeo17_074", year:2017, subject:"entomology", question:"'Helicoverpa armigera' (American bollworm/gram pod borer) damages:", options:["Only cotton","Multiple crops including cotton, chickpea, tomato, sorghum, maize (highly polyphagous)","Only pulses","Only cereals"], correct:1, explanation:"H. armigera is one of the most polyphagous pest species — attacking over 180 plant species including cotton bolls (cotton bollworm), chickpea pods (gram pod borer), tomato fruits, and many other crops, causing significant economic damage." },
  { id:"aeo17_075", year:2017, subject:"entomology", question:"The most effective management strategy for Bt-cotton resistance in pink bollworm is:", options:["Using higher Bt doses","Planting non-Bt cotton refuge (20% area) around Bt cotton to prevent complete selection pressure","Stopping Bt cotton cultivation","Using more insecticide sprays"], correct:1, explanation:"Refuge strategy (IRM — Insecticide Resistance Management) for Bt cotton: plant 20% non-Bt cotton (refuge) to maintain susceptible pink bollworm population. Mating between resistant (from Bt fields) and susceptible insects delays resistance development." },
  { id:"aeo17_076", year:2017, subject:"plant-pathology", question:"'Early blight' of potato and tomato is caused by:", options:["Phytophthora infestans","Alternaria solani","Fusarium solani","Pythium ultimum"], correct:1, explanation:"Early blight of potato and tomato is caused by Alternaria solani. Symptoms: target-board (concentric ring) lesions on older leaves, starting as dark brown spots. Managed by Mancozeb/Chlorothalonil sprays. Distinguished from late blight (Phytophthora)." },
  { id:"aeo17_077", year:2017, subject:"entomology", question:"'Yellow sticky traps' are used for monitoring which pest in vegetable crops?", options:["Stem borers","Whiteflies, aphids, and leaf miners (attracted to yellow colour)","Cutworms","Root grubs"], correct:1, explanation:"Yellow sticky traps (25×30 cm yellow cards coated with sticky material) are used for monitoring whiteflies, aphids, leaf miners, and thrips — all of which are attracted to the colour yellow. Trap count helps make ETL-based spray decisions." },
  { id:"aeo17_078", year:2017, subject:"plant-pathology", question:"'Anthracnose' disease in chilli and mango is caused by:", options:["Fusarium sp.","Colletotrichum gloeosporioides/C. capsici","Phytophthora sp.","Botrytis cinerea"], correct:1, explanation:"Anthracnose of chilli (C. capsici) and mango (C. gloeosporioides) causes dark, sunken, water-soaked lesions on fruits. The pathogen infects immature fruits and the disease becomes apparent during ripening. Major post-harvest disease of both crops." },
  { id:"aeo17_079", year:2017, subject:"entomology", question:"'Biocontrol using NPV' (Nuclear Polyhedrosis Virus) is effective against:", options:["All insect pests equally","Lepidopteran larvae (caterpillars) — highly specific","Aphids and whiteflies","Soil insects"], correct:1, explanation:"NPV (Nuclear Polyhedrosis Virus) is a baculovirus that is highly host-specific and effective against lepidopteran larvae. Helicoverpa NPV (HaNPV, at 250 LE/ha) and Spodoptera NPV are commercially produced for management of respective pests." },
  { id:"aeo17_080", year:2017, subject:"plant-pathology", question:"'Integrated Disease Management' (IDM) in rice includes:", options:["Using only fungicides","Combination of resistant varieties, cultural practices, bio-control (Pseudomonas, Trichoderma), and judicious chemical use","Using maximum pesticides","Avoiding any chemical use"], correct:1, explanation:"IDM combines: resistant varieties (blast-resistant MTU 1010, BLB-resistant BPT 5204), cultural practices (balanced fertilization, proper spacing), biocontrol (Pseudomonas fluorescens for blast, BLB), and need-based fungicide/bactericide applications." },
  { id:"aeo17_081", year:2017, subject:"entomology", question:"'Spray schedule' based IPM for cotton recommends first spray at:", options:["At sowing","At seedling stage (14 DAS) against soil-borne pests","Only at boll development stage","At 45–60 DAS when ETL is reached for sucking pests"], correct:3, explanation:"Cotton IPM spray calendar: avoid prophylactic sprays. First spray at 45–60 DAS only when sucking pest ETL is reached (jassid: 3/leaf, thrips: 5/leaf, whitefly: 6 adults/leaf). Early sprays destroy natural enemies that control pests naturally." },
  { id:"aeo17_082", year:2017, subject:"plant-pathology", question:"'Charcoal rot' of sorghum and soybean is caused by:", options:["Rhizoctonia solani","Macrophomina phaseolina","Sclerotinia sclerotiorum","Phytophthora sojae"], correct:1, explanation:"Charcoal rot (dry weather disease) is caused by Macrophomina phaseolina — a soil-borne fungus that produces microsclerotia (giving the characteristic black/charcoal colour in infected tissue). It is most severe under drought and heat stress conditions." },
  { id:"aeo17_083", year:2017, subject:"entomology", question:"'Leaf curl' of chilli is caused by:", options:["Fungal pathogen","Thrips (Scirtothrips dorsalis) — secondary to possible Chilli Leaf Curl Virus (ChiLCV)","Bacterial infection","Nutrient deficiency"], correct:1, explanation:"Chilli leaf curl complex: Thrips (Scirtothrips dorsalis, yellow thrips) cause upward curling of leaves through feeding. Some cases involve Chilli Leaf Curl Virus (ChiLCV, begomovirus) transmitted by thrips. Management: imidacloprid/spinosad for thrips." },
  { id:"aeo17_084", year:2017, subject:"plant-pathology", question:"'Bactericide' Copper Oxychloride (COC) is used at what concentration for bacterial diseases?", options:["0.05% (0.5g/l)","0.3% (3g/l) spray","5% spray","10% soil drench"], correct:1, explanation:"Copper Oxychloride (COC/Blitox) is used as foliar spray at 0.3% (3g per litre water) or 600g/200L water/acre for managing bacterial diseases (rice BLB, citrus canker, vegetable bacterial blight) and as a protectant fungicide." },
  { id:"aeo17_085", year:2017, subject:"entomology", question:"Which of the following is a beneficial insect that should be protected while spraying insecticides?", options:["Helicoverpa armigera","Chrysoperla carnea (lacewing — natural enemy/predator)","Spodoptera litura","Anomis flava"], correct:1, explanation:"Chrysoperla carnea (common lacewing, green lacewing) is an important generalist predator. Both larvae and adults prey on aphids, thrips, mites, small caterpillars, and whiteflies. It is susceptible to broad-spectrum insecticides and should be protected." },

  // Horticulture (10 Qs)
  { id:"aeo17_086", year:2017, subject:"horticulture", question:"The term 'Hardening' of seedlings in vegetable nursery refers to:", options:["Adding fertilizers to make seedlings strong","Gradually exposing nursery seedlings to outdoor conditions before transplanting to reduce transplant shock","Treating seeds with chemicals","Applying growth regulators"], correct:1, explanation:"Hardening is the process of gradually acclimatising nursery seedlings (grown under protected conditions) to outdoor/field conditions — reducing irrigation, increasing light exposure, and lowering temperature over 7–10 days before transplanting." },
  { id:"aeo17_087", year:2017, subject:"horticulture", question:"'Himayat' (Imam Pasand) mango variety is special because:", options:["It is resistant to mango hoppers","It is the largest mango with distinctive elongated shape and very sweet flesh","It has earliest maturity","It is suitable only for processing"], correct:1, explanation:"Himayat (Imam Pasand) mango from Telangana/AP is called 'Emperor among mangoes' — known for its very large size (600–900g), elongated shape, yellow skin, fibreless flesh, and exceptional sweetness. It has a GI tag and commands premium price." },
  { id:"aeo17_088", year:2017, subject:"horticulture", question:"'Tissue culture' propagated banana planting material is superior because:", options:["Higher yield guaranteed always","Disease-free (virus-free), true-to-type uniform plants with early bearing","Cheaper than suckers","Better drought tolerance"], correct:1, explanation:"Tissue culture (TC) banana plants are superior to conventional suckers because: they are disease-free (free from bunchy top virus, banana mosaic), genetically uniform, have better stand establishment, earlier production, and higher yield." },
  { id:"aeo17_089", year:2017, subject:"horticulture", question:"'Drip irrigation' in chilli at Telangana Agricultural University recommendation saves water by:", options:["10%","25–30%","40–50%","60–70%"], correct:2, explanation:"Drip irrigation in chilli saves approximately 40–50% water compared to traditional furrow irrigation while achieving the same or higher yield. It also reduces fungal disease incidence (no wet foliage), improves fertilizer use efficiency through fertigation." },
  { id:"aeo17_090", year:2017, subject:"horticulture", question:"'Cucumber Mosaic Virus' (CMV) in vegetables is transmitted by:", options:["Beetles (contact)","Aphids — in non-persistent manner","Whitefly — persistent manner","Nematodes"], correct:1, explanation:"CMV (one of the most common plant viruses affecting over 1,200 species) is primarily transmitted by aphids (more than 80 species) in a non-persistent (stylet-borne) manner — transmitted within seconds of probing and lost quickly." },
  { id:"aeo17_091", year:2017, subject:"horticulture", question:"'Protected cultivation' (polyhouse/greenhouse) in Telangana is promoted for:", options:["All field crops","High-value vegetables (capsicum, tomato, cucumber), flowers, and seedling nurseries","Only research purposes","Only during summer season"], correct:1, explanation:"Protected cultivation in Telangana is promoted for high-value crops that benefit from climate control: capsicum, cherry tomato, gerbera, carnation, and vegetable seedling nurseries. Subsidy is available under NHM for polyhouse construction." },
  { id:"aeo17_092", year:2017, subject:"horticulture", question:"'Telangana State Horticulture Nursery Development' programme focuses on:", options:["Mass production of common seeds","Producing quality planting material (grafts, budded plants, TC plants) to meet the planting material demand","Marketing of vegetables only","Post-harvest infrastructure only"], correct:1, explanation:"State Horticulture Nursery programme establishes government and private certified nurseries to produce quality planting material (grafted mango, budded citrus, TC banana, rooted cuttings of guava, grape) to meet farmers' demand at affordable prices." },
  { id:"aeo17_093", year:2017, subject:"horticulture", question:"Which is the correct arrangement of mango varieties in order of their harvest season (earliest to latest)?", options:["Banganapalle → Dasheri → Neelam → Alphonso","Banganapalle → Alphonso → Neelam → Dasheri","Totapuri → Banganapalle → Neelam → Alphonso","Alphonso → Totapuri → Banganapalle → Neelam"], correct:3, explanation:"Harvest season (approximate): Alphonso (Hapus) — March/April (earliest South India), Totapuri/Banganapalle — April/May, Dashehari (North India) — June/July, Neelam — June/July (latest in South India). In Telangana context: Alphonso earliest, Neelam latest." },
  { id:"aeo17_094", year:2017, subject:"horticulture", question:"'Pit planting' method in mango orchards: pit size recommended is:", options:["30×30×30 cm","60×60×60 cm","1×1×1 m","1.5×1.5×1.5 m"], correct:1, explanation:"Standard pit size for mango planting is 60×60×60 cm (1 cubic foot). The pit is filled with a mixture of FYM (25 kg), SSP (500g), and Aldrin/Chlorpyrifos (white ant protection) 15–30 days before planting to allow settling." },
  { id:"aeo17_095", year:2017, subject:"horticulture", question:"National Horticulture Research and Development Foundation (NHRDF) is headquartered at:", options:["Hyderabad","Nasik (Nashik), Maharashtra","Ludhiana","Bengaluru"], correct:1, explanation:"NHRDF (National Horticulture Research and Development Foundation), established 1977, is headquartered at Nashik, Maharashtra. It conducts research on onion, garlic, vegetables, and provides technical support to vegetable growers across India." },

  // Government Schemes & General Agriculture (5 Qs)
  { id:"aeo17_096", year:2017, subject:"general-agriculture", question:"'Pradhan Mantri Krishi Sinchai Yojana' (PMKSY) aims at:", options:["Only drip irrigation promotion","Har Khet Ko Pani (irrigation to every farm) + More Crop Per Drop (water use efficiency)","Rural employment guarantee","Agricultural credit guarantee"], correct:1, explanation:"PMKSY (launched 2015) has two complementary objectives: 'Har Khet Ko Pani' — ensuring irrigation access to all farmland; and 'More Crop Per Drop' — improving WUE through micro-irrigation (drip, sprinkler), watershed development, and water conservation." },
  { id:"aeo17_097", year:2017, subject:"general-agriculture", question:"'National Livestock Mission' (NLM) promotes:", options:["Import of exotic cattle breeds","Entrepreneurship development in animal husbandry, poultry, fodder production, and breed improvement","Only dairy development","Cotton-based textile industry"], correct:1, explanation:"NLM promotes entrepreneurship in animal husbandry sector — processing units, feed/fodder businesses, breed improvement, and risk management for livestock farmers. It covers all species: cattle, buffalo, sheep, goat, pig, and poultry." },
  { id:"aeo17_098", year:2017, subject:"general-agriculture", question:"'Integrated Scheme for Agricultural Marketing' (ISAM) supports:", options:["Only MSP procurement","Agricultural warehousing infrastructure, cold chains, market intelligence, and e-NAM integration","Only seed distribution","Farm mechanisation only"], correct:1, explanation:"ISAM (earlier separate schemes merged in 2014) supports: rural primary warehouses/silos, cold storage infrastructure (NCCD), Agmark grading laboratories, market intelligence and news dissemination (AGMARKNET), and e-NAM integration." },
  { id:"aeo17_099", year:2017, subject:"general-agriculture", question:"India's rank in world oilseed production is approximately:", options:["First","Second","Third","Fourth"], correct:1, explanation:"India is the second-largest oilseed producing country in the world (after China), producing approximately 35–40 million tonnes of oilseeds annually. Major oilseeds: groundnut, rapeseed-mustard, soybean, sunflower, sesame, linseed, safflower." },
  { id:"aeo17_100", year:2017, subject:"general-agriculture", question:"'Dryland farming' in Telangana covers approximately what percentage of net sown area?", options:["20%","40%","60%","80%"], correct:2, explanation:"Approximately 60–65% of Telangana's net sown area (about 75 lakh ha of total 140 lakh ha) is under dryland farming (rainfed, non-irrigated). The remaining 35–40% has some form of irrigation (surface or groundwater)." },
] as PYQQuestion[];
